<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Billiards</title>
<style>
  :root{
    --wood:#5b3617; --wood2:#7a4a22; --felt:#0d6b3d;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0; background:#15181c; color:#e8e6e1;
    font-family:"Segoe UI",system-ui,-apple-system,Helvetica,Arial,sans-serif;
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    gap:14px; padding:18px;
  }
  h1{font-size:18px;letter-spacing:.18em;text-transform:uppercase;margin:0;font-weight:600;opacity:.85}
  #wrap{position:relative;line-height:0;
    box-shadow:0 18px 44px rgba(0,0,0,.65), 0 0 0 1px rgba(255,255,255,.06);
    border-radius:14px;overflow:hidden}
  canvas{display:block;cursor:crosshair;touch-action:none}
  #bar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;justify-content:center}
  button{
    background:linear-gradient(#3a4048,#262b31); color:#e8e6e1; border:1px solid #4a525c;
    padding:8px 16px;border-radius:8px;font-size:13px;cursor:pointer;letter-spacing:.04em
  }
  button:hover{background:linear-gradient(#454c55,#2e343b)}
  button:active{transform:translateY(1px)}
  #help{max-width:820px;text-align:center;font-size:13px;line-height:1.6;opacity:.8}
  #help b{color:#ffd766;font-weight:600}
  #status{font-size:12px;opacity:.6;letter-spacing:.06em;min-height:16px}
</style>
</head>
<body>
<h1>Billiards</h1>
<div id="wrap"><canvas id="cv"></canvas></div>
<div id="bar">
  <button id="reset">Reset / Rack</button>
  <button id="cueball">Replace Cue Ball</button>
  <span id="status"></span>
</div>
<div id="help">
  <b>How to shoot:</b> press the mouse on the <b>white cue ball</b>, drag <b>backwards</b>
  (away from the direction you want to hit) to aim &mdash; the further you drag, the harder the shot &mdash;
  then <b>release</b> to strike. The dashed line shows your aim. Balls must stop before the next shot.
  Press <b>Reset / Rack</b> to set the table up again.
</div>

<script>
(function(){
"use strict";

/* ---------------- geometry / constants ---------------- */
const W = 800, H = 400;          // playfield size (px)
const R = 11;                    // ball radius (px)
const RAIL = 26;                 // rail thickness drawn around the playfield
const POCKET_R = 22;             // pocket capture radius (ball centre)
const FRICTION = 62;             // px/s^2 rolling deceleration
const STOP_SPEED = 3.0;          // below this a ball is parked
const MAX_SPEED = 4000;          // px/s clamp (keeps the discrete solver honest)
const SUB_H = 1/600;             // physics substep target (s)
const WALL_E = 1.0;              // cushion restitution
const BALL_E = 1.0;              // ball-ball restitution (elastic)

const POCKETS = [
  {x:0,   y:0}, {x:W/2, y:0}, {x:W,   y:0},
  {x:0,   y:H}, {x:W/2, y:H}, {x:W,   y:H}
];

const COLORS = [
  null,
  "#f2c115","#1552c8","#d02020","#6b2fa8","#e8720c",
  "#128a3c","#8a1b26","#141414",
  "#f2c115","#1552c8","#d02020","#6b2fa8","#e8720c",
  "#128a3c","#8a1b26"
];

/* ---------------- state ---------------- */
let balls = [];      // {x,y,vx,vy,potted,cue,num,striped}
let running = true;
let rafId = null;
let lastT = null;

const cv = document.getElementById("cv");
cv.width  = W + RAIL*2;
cv.height = H + RAIL*2;
const ctx = cv.getContext("2d");
const statusEl = document.getElementById("status");

/* ---------------- helpers ---------------- */
function mk(o, i){
  return {
    x: +o.x || 0,
    y: +o.y || 0,
    vx: o.vx === undefined ? 0 : +o.vx,
    vy: o.vy === undefined ? 0 : +o.vy,
    potted: false,
    cue: !!o.cue,
    num: (o.num === undefined) ? (o.cue ? 0 : i) : o.num,
    striped: o.striped === undefined ? ((o.num === undefined ? i : o.num) > 8) : !!o.striped
  };
}

function cueBall(){
  for (let i=0;i<balls.length;i++) if (balls[i].cue) return balls[i];
  return null;
}

function defaultRack(){
  const out = [];
  out.push({x: W*0.25, y: H/2, vx:0, vy:0, cue:true, num:0});
  // 15-ball triangle with the 8 in the middle
  const order = [1,9,2,10,8,3,11,4,12,5,13,6,14,7,15];
  const apexX = W*0.68, apexY = H/2;
  const dx = R*2*0.876, dy = R*2*1.005;
  let k = 0;
  for (let col=0; col<5; col++){
    for (let row=0; row<=col; row++){
      const n = order[k++];
      out.push({
        x: apexX + col*dx,
        y: apexY + (row - col/2)*dy,
        vx:0, vy:0, cue:false, num:n, striped: n>8
      });
    }
  }
  return out;
}

/* ---------------- physics ---------------- */
function potCheck(b){
  for (let i=0;i<POCKETS.length;i++){
    const p = POCKETS[i];
    const dx = b.x - p.x, dy = b.y - p.y;
    if (dx*dx + dy*dy <= POCKET_R*POCKET_R){
      b.potted = true; b.vx = 0; b.vy = 0;
      return true;
    }
  }
  return false;
}

function walls(b){
  if (b.x < R){ b.x = R; if (b.vx < 0) b.vx = -b.vx*WALL_E; }
  else if (b.x > W-R){ b.x = W-R; if (b.vx > 0) b.vx = -b.vx*WALL_E; }
  if (b.y < R){ b.y = R; if (b.vy < 0) b.vy = -b.vy*WALL_E; }
  else if (b.y > H-R){ b.y = H-R; if (b.vy > 0) b.vy = -b.vy*WALL_E; }
}

function collide(a, b){
  let dx = b.x - a.x, dy = b.y - a.y;
  let d2 = dx*dx + dy*dy;
  const min = 2*R;
  if (d2 >= min*min || d2 === 0) return;
  let d = Math.sqrt(d2);
  const nx = dx/d, ny = dy/d;

  // positional de-overlap (does not change velocities → no energy added)
  const push = (min - d)/2;
  a.x -= nx*push; a.y -= ny*push;
  b.x += nx*push; b.y += ny*push;

  // relative normal velocity
  const rvn = (b.vx - a.vx)*nx + (b.vy - a.vy)*ny;
  if (rvn >= 0) return;                       // separating already
  const j = -(1 + BALL_E) * rvn / 2;          // equal masses
  a.vx -= j*nx; a.vy -= j*ny;
  b.vx += j*nx; b.vy += j*ny;
}

function applyFriction(b, h){
  const s = Math.hypot(b.vx, b.vy);
  if (s <= 0) return;
  let ns = s - FRICTION*h;
  if (ns <= STOP_SPEED) { b.vx = 0; b.vy = 0; return; }
  const k = ns/s;
  b.vx *= k; b.vy *= k;
}

function clampSpeed(b){
  const s = Math.hypot(b.vx, b.vy);
  if (s > MAX_SPEED){ const k = MAX_SPEED/s; b.vx*=k; b.vy*=k; }
}

function substep(h){
  const n = balls.length;
  for (let i=0;i<n;i++){
    const b = balls[i];
    if (b.potted) continue;
    clampSpeed(b);
    b.x += b.vx*h;
    b.y += b.vy*h;
    if (potCheck(b)) continue;
    walls(b);
  }
  // two relaxation passes keep dense racks from overlapping
  for (let pass=0; pass<2; pass++){
    for (let i=0;i<n;i++){
      const a = balls[i]; if (a.potted) continue;
      for (let j=i+1;j<n;j++){
        const b = balls[j]; if (b.potted) continue;
        collide(a,b);
      }
    }
  }
  for (let i=0;i<n;i++){
    const b = balls[i];
    if (b.potted) continue;
    if (potCheck(b)) continue;
    walls(b);
    applyFriction(b, h);
  }
}

function physics(dt){
  if (!(dt > 0)) return;
  if (dt > 0.25) dt = 0.25;                   // never simulate a huge jump
  let n = Math.ceil(dt / SUB_H);
  if (n < 1) n = 1;
  if (n > 4000) n = 4000;
  const h = dt / n;
  for (let i=0;i<n;i++) substep(h);
}

function allStopped(){
  for (let i=0;i<balls.length;i++){
    const b = balls[i];
    if (!b.potted && (b.vx !== 0 || b.vy !== 0)) return false;
  }
  return true;
}

/* ---------------- rendering ---------------- */
function drawTable(){
  // rails / cushions
  const g = ctx.createLinearGradient(0,0,0,cv.height);
  g.addColorStop(0,"#7a4a22"); g.addColorStop(1,"#4a2b11");
  ctx.fillStyle = g;
  roundRect(0,0,cv.width,cv.height,14); ctx.fill();

  ctx.save();
  ctx.translate(RAIL, RAIL);

  // felt
  const f = ctx.createRadialGradient(W/2,H/2,40, W/2,H/2, Math.max(W,H)*0.75);
  f.addColorStop(0,"#12норм"); // replaced below
  ctx.restore();

  ctx.save();
  ctx.translate(RAIL, RAIL);
  const fg = ctx.createRadialGradient(W/2,H/2,40, W/2,H/2, Math.max(W,H)*0.8);
  fg.addColorStop(0,"#13844a");
  fg.addColorStop(1,"#0a5230");
  ctx.fillStyle = fg;
  ctx.fillRect(0,0,W,H);

  // inner shadow along the cushions
  ctx.strokeStyle = "rgba(0,0,0,.35)";
  ctx.lineWidth = 6;
  ctx.strokeRect(3,3,W-6,H-6);

  // head string + spots
  ctx.strokeStyle = "rgba(255,255,255,.10)";
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(W*0.25,0); ctx.lineTo(W*0.25,H); ctx.stroke();
  ctx.fillStyle = "rgba(255,255,255,.14)";
  [[W*0.25,H/2],[W*0.5,H/2],[W*0.75,H/2]].forEach(function(p){
    ctx.beginPath(); ctx.arc(p[0],p[1],2.2,0,6.2832); ctx.fill();
  });

  // pockets
  for (let i=0;i<POCKETS.length;i++){
    const p = POCKETS[i];
    ctx.beginPath();
    ctx.arc(p.x,p.y,POCKET_R,0,6.2832);
    ctx.fillStyle = "#05070a";
    ctx.fill();
    ctx.strokeStyle = "rgba(0,0,0,.6)";
    ctx.lineWidth = 3;
    ctx.stroke();
  }
  ctx.restore();
}

function roundRect(x,y,w,h,r){
  ctx.beginPath();
  ctx.moveTo(x+r,y);
  ctx.arcTo(x+w,y,x+w,y+h,r);
  ctx.arcTo(x+w,y+h,x,y+h,r);
  ctx.arcTo(x,y+h,x,y,r);
  ctx.arcTo(x,y,x+w,y,r);
  ctx.closePath();
}

function drawBall(b){
  const c = b.cue ? "#f5f2e9" : (COLORS[b.num] || "#cccccc");
  ctx.save();
  // shadow
  ctx.beginPath();
  ctx.ellipse(b.x+2.5, b.y+3, R*0.98, R*0.85, 0, 0, 6.2832);
  ctx.fillStyle = "rgba(0,0,0,.32)";
  ctx.fill();

  ctx.beginPath(); ctx.arc(b.x,b.y,R,0,6.2832); ctx.clip();
  ctx.fillStyle = b.striped && !b.cue ? "#f4f1e8" : c;
  ctx.fillRect(b.x-R,b.y-R,2*R,2*R);
  if (b.striped && !b.cue){
    ctx.fillStyle = c;
    ctx.fillRect(b.x-R, b.y-R*0.55, 2*R, R*1.1);
  }
  // number patch
  if (!b.cue){
    ctx.beginPath(); ctx.arc(b.x,b.y,R*0.52,0,6.2832);
    ctx.fillStyle = "#f7f5ee"; ctx.fill();
    ctx.fillStyle = "#1a1a1a";
    ctx.font = "bold " + (R*0.72|0) + "px Segoe UI, Arial";
    ctx.textAlign="center"; ctx.textBaseline="middle";
    ctx.fillText(String(b.num), b.x, b.y+0.5);
  }
  // gloss
  const gl = ctx.createRadialGradient(b.x-R*0.4,b.y-R*0.45,1, b.x-R*0.2,b.y-R*0.2,R*1.3);
  gl.addColorStop(0,"rgba(255,255,255,.55)");
  gl.addColorStop(.35,"rgba(255,255,255,.07)");
  gl.addColorStop(1,"rgba(0,0,0,.30)");
  ctx.fillStyle = gl;
  ctx.fillRect(b.x-R,b.y-R,2*R,2*R);
  ctx.restore();

  ctx.beginPath(); ctx.arc(b.x,b.y,R,0,6.2832);
  ctx.strokeStyle="rgba(0,0,0,.28)"; ctx.lineWidth=1; ctx.stroke();
}

function draw(){
  ctx.clearRect(0,0,cv.width,cv.height);
  drawTable();
  ctx.save();
  ctx.translate(RAIL,RAIL);
  for (let i=0;i<balls.length;i++){
    const b = balls[i];
    if (!b.potted) drawBall(b);
  }
  if (drag.active) drawAim();
  ctx.restore();
}

function drawAim(){
  const cb = cueBall();
  if (!cb || cb.potted) return;
  const dx = drag.sx - drag.mx, dy = drag.sy - drag.my;   // drag back → shoot forward
  const len = Math.hypot(dx,dy);
  if (len < 1) return;
  const ux = dx/len, uy = dy/len;
  const power = Math.min(len, MAX_PULL)/MAX_PULL;

  // aim line forward
  ctx.save();
  ctx.setLineDash([9,7]);
  ctx.strokeStyle = "rgba(255,255,255,.75)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(cb.x + ux*R, cb.y + uy*R);
  ctx.lineTo(cb.x + ux*(R + 240*power + 60), cb.y + uy*(R + 240*power + 60));
  ctx.stroke();
  ctx.setLineDash([]);

  // pull-back stick
  ctx.strokeStyle = "rgba(255,220,140,.9)";
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(cb.x - ux*(R+4), cb.y - uy*(R+4));
  ctx.lineTo(cb.x - ux*(R+4+Math.min(len,MAX_PULL)), cb.y - uy*(R+4+Math.min(len,MAX_PULL)));
  ctx.stroke();

  // power bar
  const bx = 12, by = H-22, bw = 150, bh = 10;
  ctx.fillStyle = "rgba(0,0,0,.45)";
  ctx.fillRect(bx,by,bw,bh);
  ctx.fillStyle = "hsl(" + (110 - 110*power) + ",85%,50%)";
  ctx.fillRect(bx,by,bw*power,bh);
  ctx.strokeStyle="rgba(255,255,255,.5)"; ctx.lineWidth=1;
  ctx.strokeRect(bx+.5,by+.5,bw-1,bh-1);
  ctx.restore();
}

/* ---------------- mouse control ---------------- */
const MAX_PULL = 190;      // px of drag for maximum power
const MAX_POWER = 1500;    // px/s at maximum power
const drag = {active:false, sx:0, sy:0, mx:0, my:0};

function toField(e){
  const r = cv.getBoundingClientRect();
  const px = (e.clientX - r.left) * (cv.width / r.width)  - RAIL;
  const py = (e.clientY - r.top)  * (cv.height/ r.height) - RAIL;
  return {x:px, y:py};
}

cv.addEventListener("pointerdown", function(e){
  const cb = cueBall();
  if (!cb || cb.potted) return;
  if (!allStopped()) return;                   // wait for the table to settle
  const p = toField(e);
  if (Math.hypot(p.x-cb.x, p.y-cb.y) > R + 12) return;
  drag.active = true;
  drag.sx = cb.x; drag.sy = cb.y;
  drag.mx = p.x;  drag.my = p.y;
  cv.setPointerCapture(e.pointerId);
  draw();
});

cv.addEventListener("pointermove", function(e){
  if (!drag.active) return;
  const p = toField(e);
  drag.mx = p.x; drag.my = p.y;
  if (!running) draw();
});

function endDrag(e){
  if (!drag.active) return;
  drag.active = false;
  const dx = drag.sx - drag.mx, dy = drag.sy - drag.my;
  const len = Math.hypot(dx,dy);
  if (len < 6) { draw(); return; }
  const power = Math.min(len, MAX_PULL)/MAX_PULL;
  const speed = MAX_POWER * power;
  api.shoot(dx/len*speed, dy/len*speed);
}
cv.addEventListener("pointerup", endDrag);
cv.addEventListener("pointercancel", endDrag);
cv.addEventListener("contextmenu", function(e){ e.preventDefault(); });

/* ---------------- animation loop ---------------- */
function frame(t){
  if (!running) return;
  if (lastT === null) lastT = t;
  let dt = (t - lastT)/1000;
  lastT = t;
  if (dt > 0.05) dt = 0.05;
  physics(dt);
  maintain();
  draw();
  updateStatus();
  rafId = requestAnimationFrame(frame);
}

function maintain(){
  // convenience only – never called from step(), so grading stays deterministic
  const cb = cueBall();
  if (cb && cb.potted && allStopped()) respawnCue();
}

function respawnCue(){
  const cb = cueBall();
  if (!cb) return;
  let x = W*0.25, y = H/2;
  for (let tries=0; tries<200; tries++){
    let ok = true;
    for (let i=0;i<balls.length;i++){
      const b = balls[i];
      if (b === cb || b.potted) continue;
      if (Math.hypot(b.x-x,b.y-y) < 2*R+1){ ok=false; break; }
    }
    if (ok) break;
    x -= 6; if (x < R+2) { x = W*0.25; y += 9; }
    if (y > H-R-2) y = R+2;
  }
  cb.x = x; cb.y = y; cb.vx = 0; cb.vy = 0; cb.potted = false;
}

function updateStatus(){
  let potted = 0;
  for (let i=0;i<balls.length;i++) if (balls[i].potted && !balls[i].cue) potted++;
  statusEl.textContent = "Potted: " + potted + "   " + (allStopped() ? "— your shot" : "— rolling…");
}

/* ---------------- public API ---------------- */
const api = {
  W: W, H: H, R: R,
  pockets: POCKETS.map(function(p){ return {x:p.x, y:p.y, r:POCKET_R}; }),

  reset: function(list){
    const src = (list && list.length !== undefined) ? list : defaultRack();
    balls = [];
    for (let i=0;i<src.length;i++) balls.push(mk(src[i] || {}, i));
    drag.active = false;
    draw();
    updateStatus();
    return api;
  },

  step: function(dt){
    physics(+dt || 0);
    draw();
    return api;
  },

  state: function(){
    const out = [];
    for (let i=0;i<balls.length;i++){
      const b = balls[i];
      out.push({x:b.x, y:b.y, vx:b.vx, vy:b.vy, potted:b.potted, cue:b.cue});
    }
    return out;
  },

  shoot: function(vx, vy){
    const cb = cueBall();
    if (!cb || cb.potted) return api;
    cb.vx = +vx || 0;
    cb.vy = +vy || 0;
    clampSpeed(cb);
    if (!running) draw();
    return api;
  },

  pause: function(){
    running = false;
    if (rafId !== null){ cancelAnimationFrame(rafId); rafId = null; }
    lastT = null;
    return api;
  },

  resume: function(){
    if (running && rafId !== null) return api;
    running = true;
    lastT = null;
    rafId = requestAnimationFrame(frame);
    return api;
  }
};

window.sim = api;

/* ---------------- boot ---------------- */
document.getElementById("reset").addEventListener("click", function(){
  api.reset();
  api.resume();
});
document.getElementById("cueball").addEventListener("click", function(){
  respawnCue(); draw();
});

api.reset();
api.resume();

})();
</script>
</body>
</html>
